#pragma once

#include <stdint.h>

/* GB2312 level-1/2 CJK bitmap font, generated by tools/gen_cjk_bitmaps.py
 * from a system font and embedded as a flash blob. 24x24 cell, 1 bit per
 * pixel, row major, MSB is the leftmost pixel. Bit set = ink.
 *
 * The table is sorted by codepoint so lookup is a binary search; arbitrary
 * Chinese event titles received over BLE can therefore be rendered without a
 * font engine or an SD card font. */

#define FONT_CJK_PX 24
#define FONT_CJK_ROW_BYTES 3
#define FONT_CJK_GLYPH_BYTES (FONT_CJK_ROW_BYTES * FONT_CJK_PX)

/* Bitmap for `codepoint`, or NULL when it is not covered. */
const uint8_t *font_cjk_lookup(uint32_t codepoint);

/* Number of glyphs in the embedded table (diagnostics / preview tool). */
int font_cjk_count(void);
